update public.recipes r
   set name_en = v.name_en, instructions_en = v.instructions_en,
       name_es = v.name_es, instructions_es = v.instructions_es
  from (values
    ('Açaí na tigela', 'Açaí bowl', 'Blend the frozen açaí with half the banana until creamy. Top with the granola, the rest of the banana in slices and the honey.', 'Açaí en bowl', 'Licúa el açaí congelado con la mitad de la banana hasta que quede cremoso. Cubre con la granola, el resto de la banana en rodajas y la miel.'),
    ('Baião de dois com queijo coalho', 'Baião de dois with grilled cheese', 'Serve the baião hot with the cheese, cubed and grilled, on top.', 'Baião de dois con queso coalho', 'Sirve el baião caliente con el queso en cubos a la plancha por encima.'),
    ('Banana com pasta de amendoim', 'Banana with peanut butter', 'Slice the banana and top with the peanut butter.', 'Banana con mantequilla de maní', 'Corta la banana en rodajas y cúbrela con la mantequilla de maní.'),
    ('Bolo de banana com aveia', 'Banana oat cake', 'Mash the bananas and mix in the eggs, oil and sugar. Add the oats and baking powder. Bake at 180 °C for 35 minutes.', 'Bizcocho de banana y avena', 'Aplasta las bananas y mezcla los huevos, el aceite y el azúcar. Añade la avena y el polvo de hornear. Hornea a 180 °C durante 35 minutos.'),
    ('Bolo de cacau fit', 'Healthy cocoa cake', 'Mash the bananas and mix in the eggs, cocoa, oats and baking powder. Bake at 180 °C for 30 minutes.', 'Bizcocho fit de cacao', 'Aplasta las bananas y mezcla los huevos, el cacao, la avena y el polvo de hornear. Hornea a 180 °C durante 30 minutos.'),
    ('Bolo de cenoura com cobertura de chocolate', 'Carrot cake with chocolate frosting', 'Blend the carrot, eggs, oil and sugar. Mix in the flour and baking powder and bake at 180 °C for 40 minutes. Melt the chocolate with the cream for the frosting.', 'Bizcocho de zanahoria con cobertura de chocolate', 'Licúa la zanahoria, los huevos, el aceite y el azúcar. Mezcla la harina y el polvo de hornear y hornea a 180 °C durante 40 minutos. Derrite el chocolate con la crema de leche para la cobertura.'),
    ('Bolo de chocolate', 'Chocolate cake', 'Mix the dry ingredients, then add the eggs, milk and oil. Bake at 180 °C for 35 minutes.', 'Bizcocho de chocolate', 'Mezcla los ingredientes secos y añade los huevos, la leche y el aceite. Hornea a 180 °C durante 35 minutos.'),
    ('Bolo de fubá', 'Cornmeal cake', 'Blend the eggs, milk, oil and sugar. Mix in the cornmeal, flour and baking powder. Bake at 180 °C for 40 minutes.', 'Bizcocho de harina de maíz', 'Licúa los huevos, la leche, el aceite y el azúcar. Mezcla la harina de maíz, la harina de trigo y el polvo de hornear. Hornea a 180 °C durante 40 minutos.'),
    ('Bolo de laranja', 'Orange cake', 'Blend the eggs, oil, sugar and juice. Mix in the flour and baking powder. Bake at 180 °C for 35 minutes.', 'Bizcocho de naranja', 'Licúa los huevos, el aceite, el azúcar y el jugo. Mezcla la harina y el polvo de hornear. Hornea a 180 °C durante 35 minutos.'),
    ('Brigadeiro proteico', 'Protein brigadeiro', 'Mix the powdered milk, whey and cocoa with the milk until it forms a dough. Roll into balls and refrigerate.', 'Brigadeiro proteico', 'Mezcla la leche en polvo, el whey y el cacao con la leche hasta formar una masa. Forma bolitas y llévalas al refrigerador.'),
    ('Carne de panela com legumes', 'Pot roast with vegetables', 'Brown the beef, cover with water and pressure-cook for 40 minutes. Add the vegetables and cook 10 more.', 'Carne a la olla con verduras', 'Dora la carne, cúbrela con agua y cocina en olla a presión durante 40 minutos. Añade las verduras y cocina 10 más.'),
    ('Carne moída com batata-doce e brócolis', 'Ground beef with sweet potato and broccoli', 'Sauté the ground beef with onion and garlic. Serve with the boiled sweet potato and broccoli.', 'Carne molida con batata y brócoli', 'Saltea la carne molida con cebolla y ajo. Sírvela con la batata y el brócoli cocidos.'),
    ('Cookies de banana e aveia', 'Banana oat cookies', 'Mash the banana and mix in the oats and chopped chocolate. Shape into flattened balls and bake at 180 °C for 15 minutes.', 'Galletas de banana y avena', 'Aplasta la banana y mezcla la avena y el chocolate picado. Forma bolitas aplanadas y hornea a 180 °C durante 15 minutos.'),
    ('Crepioca de queijo', 'Cheese crepioca (tapioca crepe)', 'Mix the eggs with the tapioca starch, pour into a greased pan and flip. Fill with the mozzarella.', 'Crepioca de queso (crepe de tapioca)', 'Mezcla los huevos con el almidón de tapioca, vierte en la sartén engrasada y da la vuelta. Rellena con la mozzarella.'),
    ('Cuscuz nordestino com ovo', 'Northeastern corn couscous with egg', 'Serve the couscous hot with the butter and the boiled eggs on top.', 'Cuscús nordestino con huevo', 'Sirve el cuscús caliente con la mantequilla y los huevos cocidos por encima.'),
    ('Escondidinho de carne seca', 'Escondidinho (dried beef and cassava bake)', 'Mash the cassava with the butter. In a baking dish, layer the shredded dried beef, cover with the purée and the cheese and broil until golden.', 'Escondidinho de carne seca', 'Aplasta la yuca con la mantequilla. En una fuente, haz una capa de carne seca deshebrada, cúbrela con el puré y el queso y gratina.'),
    ('Estrogonofe de frango com arroz', 'Chicken stroganoff with rice', 'Serve the stroganoff hot with the white rice.', 'Strogonoff de pollo con arroz', 'Sirve el strogonoff caliente con el arroz blanco.'),
    ('Feijoada com arroz e couve', 'Feijoada with rice and collard greens', 'Serve the feijoada with the rice, the sautéed collard greens and the orange in segments.', 'Feijoada con arroz y col', 'Sirve la feijoada con el arroz, la col salteada y la naranja en gajos.'),
    ('Frango com açafrão e arroz integral', 'Turmeric chicken with brown rice', 'Serve the turmeric chicken with the brown rice and the sautéed green beans.', 'Pollo con cúrcuma y arroz integral', 'Sirve el pollo con cúrcuma con el arroz integral y las judías verdes salteadas.'),
    ('Frango grelhado com arroz, feijão e salada', 'Grilled chicken with rice, beans and salad', 'Grill the seasoned chicken. Serve with the rice, the beans and the salad dressed with the olive oil.', 'Pollo a la plancha con arroz, frijoles y ensalada', 'Asa a la plancha el pollo sazonado. Sírvelo con el arroz, los frijoles y la ensalada aliñada con el aceite de oliva.'),
    ('Hambúrguer caseiro', 'Homemade burger', 'Grill the burger, melt the cheese on top and assemble in the bun with tomato, lettuce and onion.', 'Hamburguesa casera', 'Asa la hamburguesa a la plancha, derrite el queso por encima y arma en el pan con tomate, lechuga y cebolla.'),
    ('Iogurte com frutas e granola', 'Yogurt with fruit and granola', 'Layer the yogurt, chopped fruit and granola. Finish with the honey.', 'Yogur con frutas y granola', 'Arma en capas: yogur, frutas picadas y granola. Termina con la miel.'),
    ('Iogurte com mel e aveia', 'Yogurt with honey and oats', 'Mix the yogurt with the oats and honey.', 'Yogur con miel y avena', 'Mezcla el yogur con la avena y la miel.'),
    ('Lasanha à bolonhesa', 'Lasagna bolognese', 'In a baking dish, alternate layers of pasta, ground beef in tomato sauce and mozzarella. Top with parmesan and bake for 30 minutes.', 'Lasaña a la boloñesa', 'En una fuente, alterna capas de pasta, carne molida con salsa de tomate y mozzarella. Termina con parmesano y hornea durante 30 minutos.'),
    ('Macarrão à bolonhesa', 'Pasta bolognese', 'Serve the pasta with the bolognese sauce and finish with the grated parmesan.', 'Pasta a la boloñesa', 'Sirve la pasta con la salsa boloñesa y termina con el parmesano rallado.'),
    ('Maçã com queijo branco', 'Apple with fresh white cheese', 'Slice the apple and serve with cubes of minas cheese.', 'Manzana con queso blanco', 'Corta la manzana en láminas y sírvela con cubos de queso minas.'),
    ('Mingau de aveia com banana', 'Oatmeal with banana', 'Cook the oats in the milk, stirring, for 5 minutes. Serve with the banana in slices and the honey.', 'Avena cocida con banana', 'Cocina la avena en la leche revolviendo durante 5 minutos. Sírvela con la banana en rodajas y la miel.'),
    ('Misto quente', 'Grilled ham and cheese', 'Fill the bread with the ham and mozzarella, butter the outside and toast in a pan or sandwich press.', 'Sándwich mixto caliente', 'Arma el pan con el jamón y la mozzarella, unta mantequilla por fuera y dóralo en la sartén o en la sandwichera.'),
    ('Mix de castanhas', 'Mixed nuts', 'Mix the nuts. A small portion is enough to hold you until the next meal.', 'Mix de frutos secos', 'Mezcla los frutos secos. Una porción pequeña ya te sostiene hasta la próxima comida.'),
    ('Mousse de maracujá', 'Passion fruit mousse', 'Blend the juice, condensed milk and cream for 3 minutes. Refrigerate for 3 hours.', 'Mousse de maracuyá', 'Licúa el jugo, la leche condensada y la crema de leche durante 3 minutos. Lleva al refrigerador durante 3 horas.'),
    ('Omelete de legumes', 'Vegetable omelet', 'Sauté the onion, tomato and spinach. Add the beaten eggs and the cheese, cover and cook over low heat.', 'Tortilla de verduras', 'Saltea la cebolla, el tomate y la espinaca. Añade los huevos batidos y el queso, tapa y cocina a fuego bajo.'),
    ('Ovos cozidos', 'Boiled eggs', 'Boil the eggs for 10 minutes, cool in cold water and peel.', 'Huevos cocidos', 'Cocina los huevos durante 10 minutos, enfríalos en agua fría y pélalos.'),
    ('Ovos mexidos com pão integral', 'Scrambled eggs with whole-grain bread', 'Beat the eggs and stir them in the pan with the butter over low heat until set. Serve with the bread.', 'Huevos revueltos con pan integral', 'Bate los huevos y revuélvelos en la sartén con la mantequilla a fuego bajo hasta que cuajen. Sírvelos con el pan.'),
    ('Panqueca de banana fit', 'Healthy banana pancake', 'Mash the banana and mix in the eggs and oats. Brown on both sides in a nonstick pan.', 'Panqueque fit de banana', 'Aplasta la banana y mezcla los huevos y la avena. Dora por ambos lados en una sartén antiadherente.'),
    ('Peixe assado com purê de batata', 'Baked fish with mashed potatoes', 'Bake the seasoned fish. Mash the potato with the milk and butter for the purée. Serve with the salad.', 'Pescado al horno con puré de papa', 'Hornea el pescado sazonado. Aplasta la papa con la leche y la mantequilla para el puré. Sírvelo con la ensalada.'),
    ('Pipoca caseira', 'Homemade popcorn', 'Pop the corn in a pot with a drizzle of oil and salt.', 'Palomitas caseras', 'Revienta el maíz en la olla con un chorrito de aceite y sal.'),
    ('Prato feito: bife, arroz, feijão e salada', 'Prato feito: steak, rice, beans and salad', 'Grill the steak and serve with the rice, the black beans and the salad.', 'Plato del día: bistec, arroz, frijoles y ensalada', 'Asa el bistec a la plancha y sírvelo con el arroz, los frijoles negros y la ensalada.'),
    ('Pudim de leite', 'Milk flan', 'Blend the condensed milk, milk and eggs. Pour into the pan caramelized with the sugar and bake in a water bath for 1 hour.', 'Flan de leche', 'Licúa la leche condensada, la leche y los huevos. Vierte en el molde caramelizado con el azúcar y hornea a baño maría durante 1 hora.'),
    ('Pão de queijo com café com leite', 'Cheese bread with coffee and milk', 'Warm the cheese bread and serve with the brewed coffee and milk.', 'Pan de queso con café con leche', 'Calienta el pan de queso y sírvelo con el café colado y la leche.'),
    ('Pão francês com ovo e queijo', 'French roll with egg and cheese', 'Fry the egg, cover with the mozzarella to melt and put it in the roll.', 'Pan francés con huevo y queso', 'Fríe el huevo, cúbrelo con la mozzarella para que se derrita y ponlo en el pan.'),
    ('Salada caprese', 'Caprese salad', 'Alternate tomato and mozzarella slices and finish with basil and olive oil.', 'Ensalada caprese', 'Alterna rodajas de tomate y mozzarella y termina con albahaca y aceite de oliva.'),
    ('Salada de atum com ovo', 'Tuna salad with egg', 'Arrange the greens, tomato, corn, drained tuna and egg in quarters. Drizzle with the olive oil.', 'Ensalada de atún con huevo', 'Arma las hojas, el tomate, el maíz, el atún escurrido y el huevo en cuartos. Rocía con el aceite de oliva.'),
    ('Salada de frango com grão-de-bico', 'Chicken and chickpea salad', 'Cook the chickpeas (they double in weight). Mix with the chicken, greens and vegetables and dress with the olive oil.', 'Ensalada de pollo con garbanzos', 'Cocina los garbanzos (duplican su peso). Mézclalos con el pollo, las hojas y las verduras y aliña con el aceite de oliva.'),
    ('Salada de legumes no vapor', 'Steamed vegetable salad', 'Steam the vegetables until tender and season with the olive oil and salt.', 'Ensalada de verduras al vapor', 'Cocina las verduras al vapor hasta que estén tiernas y aliña con el aceite de oliva y sal.'),
    ('Salmão grelhado com legumes', 'Grilled salmon with vegetables', 'Grill the salmon with salt and lemon. Serve with the steamed potatoes, broccoli and carrot drizzled with the olive oil.', 'Salmón a la plancha con verduras', 'Asa el salmón a la plancha con sal y limón. Sírvelo con las papas, el brócoli y la zanahoria al vapor rociados con el aceite de oliva.'),
    ('Sanduíche de atum', 'Tuna sandwich', 'Drain the tuna and mix with the yogurt. Assemble in the bread with the tomato and lettuce.', 'Sándwich de atún', 'Escurre el atún y mézclalo con el yogur. Arma en el pan con el tomate y la lechuga.'),
    ('Sanduíche de frango com abacate', 'Chicken avocado sandwich', 'Mash the avocado with lemon and salt, spread on the bread and top with the chicken and tomato.', 'Sándwich de pollo con aguacate', 'Aplasta el aguacate con limón y sal, úntalo en el pan y cubre con el pollo y el tomate.'),
    ('Sanduíche de peito de peru', 'Turkey breast sandwich', 'Fill the bread with the turkey breast, fresh white cheese, arugula and tomato.', 'Sándwich de pechuga de pavo', 'Arma el pan con la pechuga de pavo, el queso blanco, la rúcula y el tomate.'),
    ('Sanduíche natural de frango', 'Chicken salad sandwich', 'Mix the shredded chicken with the ricotta and grated carrot. Assemble in the bread with the lettuce.', 'Sándwich natural de pollo', 'Mezcla el pollo deshebrado con la ricota y la zanahoria rallada. Arma en el pan con la lechuga.'),
    ('Shake de banana e pasta de amendoim', 'Banana peanut butter shake', 'Blend everything. A great post-workout for anyone looking to gain muscle.', 'Batido de banana y mantequilla de maní', 'Licúa todo. Ideal después del entrenamiento para quien quiere ganar masa muscular.'),
    ('Shake de chocolate com aveia', 'Chocolate oat shake', 'Blend the milk, whey, cocoa, oats and banana. It tastes like a milkshake.', 'Batido de chocolate con avena', 'Licúa la leche, el whey, el cacao, la avena y la banana. Sabe a malteada.'),
    ('Shake proteico de morango', 'Strawberry protein shake', 'Blend the milk, whey and strawberries until creamy. Ice makes it thicker.', 'Batido proteico de fresa', 'Licúa la leche, el whey y las fresas hasta que quede cremoso. El hielo lo deja más espeso.'),
    ('Smoothie de manga com iogurte', 'Mango yogurt smoothie', 'Blend the mango with the yogurt and oats until smooth.', 'Smoothie de mango con yogur', 'Licúa el mango con el yogur y la avena hasta que quede liso.'),
    ('Suco verde detox', 'Green detox juice', 'Blend the collard greens with the orange juice, apple and lemon. Strain if you prefer.', 'Jugo verde detox', 'Licúa la col con el jugo de naranja, la manzana y el limón. Cuela si lo prefieres.'),
    ('Tabule', 'Tabbouleh', 'Serve the tabbouleh chilled, with a squeeze of lemon.', 'Tabulé', 'Sirve el tabulé frío, con un chorrito de limón.'),
    ('Tapioca de frango com queijo', 'Chicken and cheese tapioca', 'Spread the tapioca starch in a hot pan until it binds. Fill with the shredded chicken and the cheese and fold.', 'Tapioca de pollo con queso', 'Extiende el almidón de tapioca en la sartén caliente hasta que se una. Rellena con el pollo deshebrado y el queso y dobla.'),
    ('Torrada com ricota e tomate', 'Toast with ricotta and tomato', 'Spread the ricotta on the toast and top with the tomato in slices. Season to taste.', 'Tostada con ricota y tomate', 'Unta la ricota en las tostadas y cúbrelas con el tomate en rodajas. Sazona al gusto.'),
    ('Vitamina de abacate', 'Avocado smoothie', 'Blend the avocado with the milk and honey. Serve chilled.', 'Batido de aguacate', 'Licúa el aguacate con la leche y la miel. Sírvelo frío.'),
    ('Vitamina de banana com aveia', 'Banana oat smoothie', 'Blend everything for 1 minute. Serve chilled.', 'Batido de banana con avena', 'Licúa todo durante 1 minuto. Sírvelo frío.'),
    ('Vitamina de mamão com laranja', 'Papaya orange smoothie', 'Blend the papaya with the orange juice and oats. Drink right away.', 'Batido de papaya con naranja', 'Licúa la papaya con el jugo de naranja y la avena. Bébelo enseguida.'),
    ('Yakisoba', 'Yakisoba', 'Heat the yakisoba and serve right away.', 'Yakisoba', 'Calienta el yakisoba y sírvelo enseguida.')
  ) as v(name, name_en, instructions_en, name_es, instructions_es)
 where r.user_id is null and r.name = v.name and r.name_en is null and r.name_es is null;
